def bbox(g,v):
    rs=[i for i,r in enumerate(g) for x in r if x==v]
    cs=[j for i,r in enumerate(g) for j,x in enumerate(r) if x==v]
    return min(rs),max(rs),min(cs),max(cs)

def transform(g):
    H,W=len(g),len(g[0])
    br0,br1,bc0,bc1=bbox(g,2)
    # 2-line: check if horizontal (full row) or vertical
    horiz = sum(1 for x in g[br0] if x==2) > 1
    out=[row[:] for row in g]
    r0,r1,c0,c1=bbox(g,0)
    if horiz:
        m=br0
        if m>r1:  # marker below shape
            shift=m-1-r1
            rr0,rr1=r0+shift,r1+shift
        else:
            shift=m+1-r0
            rr0,rr1=r0+shift,r1+shift
        # move zeros
        new=[[0]*W for _ in range(H)]
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
                if g[i][j]==0:
                    new[i+shift][j]=0
        # 8 line just beyond far side
        line = rr0-1 if m>rr1 else rr1+1
        for j in range(W): new[line][j]=8
        # keep marker rows? In demo2, marker row kept
        for j in range(W): new[m]=g[m]
        return new
    else:
        m=bc0
        if m>c1:
            shift=m-1-c1
        else:
            shift=m+1-c0
        new=[[0]*W for _ in range(H)]
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
                if g[i][j]==0:
                    new[i][j+shift]=0
        line = c0+shift-1 if m>c1 else c1+shift+1
        for i in range(H): new[i][line]=8
        for i in range(H): new[i][m]=g[i][m]
        return new

